/**
 * The registry site is a publisher: `web/public/catalog.json` is model context
 * for addon authors and the machine-readable surface for the directory. If an
 * entry there is not a valid v3 manifest, the site is publishing a manifest the
 * client cannot install, so this test parses the emitted file with the real
 * parser instead of trusting the emitter.
 *
 * The file is generated by `web/scripts/emit-surfaces.mjs` (run by `prebuild`),
 * so the seed and the emitter are covered from the publishing side:
 * `web/src/data/addons.spec.ts` covers the seed, this covers the artifact.
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { TYPE_BOOK } from '../src/constants';
import { parseManifestV3 } from '../src/manifest';

const CATALOG_URL = new URL('../../../web/public/catalog.json', import.meta.url);

interface CatalogAddon {
  id?: unknown;
  name?: unknown;
  version?: unknown;
  manifest?: unknown;
}

interface CatalogFile {
  site?: unknown;
  count?: unknown;
  addons?: unknown;
}

function readCatalog(): CatalogFile {
  return JSON.parse(readFileSync(fileURLToPath(CATALOG_URL), 'utf8')) as CatalogFile;
}

function addonsOf(catalog: CatalogFile): CatalogAddon[] {
  expect(Array.isArray(catalog.addons), 'catalog.json must expose an addons array').toBe(true);
  return catalog.addons as CatalogAddon[];
}

function encode(value: unknown): Uint8Array {
  return new TextEncoder().encode(JSON.stringify(value));
}

describe('registry catalog.json publishes v3 manifests', () => {
  it('declares a count that matches the published entries', () => {
    const catalog = readCatalog();
    const addons = addonsOf(catalog);

    expect(addons.length, 'catalog.json must publish at least one addon').toBeGreaterThan(0);
    expect(catalog.count, 'catalog.json count must match the number of published addons').toBe(
      addons.length,
    );
  });

  it('every published entry carries a manifest that parseManifestV3 accepts', () => {
    const addons = addonsOf(readCatalog());

    for (const [index, addon] of addons.entries()) {
      const label = `catalog.json addons[${index}] ("${String(addon.id)}")`;
      expect(
        addon.manifest !== null && typeof addon.manifest === 'object',
        `${label} must publish a manifest object`,
      ).toBe(true);

      const parse = () => parseManifestV3(encode(addon.manifest), 'application/json');
      expect(parse, `${label} publishes a manifest that is not valid v3`).not.toThrow();
      const manifest = parse();

      expect(manifest.id, `${label}.manifest.id must match the entry id`).toBe(addon.id);
      expect(manifest.name, `${label}.manifest.name must match the entry name`).toBe(addon.name);
      expect(manifest.version, `${label}.manifest.version must match the entry version`).toBe(
        addon.version,
      );
      expect(
        manifest.resources.length,
        `${label} must publish at least one resource`,
      ).toBeGreaterThan(0);
      for (const catalogEntry of manifest.catalogs) {
        expect(
          catalogEntry.type,
          `${label}.manifest.catalogs must declare the single book type`,
        ).toBe(TYPE_BOOK);
      }
    }
  });

  it('publishes each addon id exactly once', () => {
    const ids = addonsOf(readCatalog()).map((addon) => String(addon.id));
    expect(new Set(ids).size, `published ids must be unique, got: ${ids.join(', ')}`).toBe(
      ids.length,
    );
  });
});
